'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Computes the Cartesian power for a double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the power.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var zeros = require( '@stdlib/ndarray/zeros' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = new Float64Vector( [ 1.0, 2.0 ] );
* var out = zeros( [ 4, 2 ], {
*     'dtype': 'float64'
* });
*
* var k = scalar2ndarray( 2, {
*     'dtype': 'int32'
* });
*
* var v = dcartesianPower( [ x, out, k ] );
* // returns <ndarray>[ [ 1.0, 1.0 ], [ 1.0, 2.0 ], [ 2.0, 1.0 ], [ 2.0, 2.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
function dcartesianPower( arrays ) {
	var out = arrays[ 1 ];
	var x = arrays[ 0 ];
	var k = arrays[ 2 ];
	addon( getData( x ), serialize( x ), getData( out ), serialize( out ), getData( k ), serialize( k ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

module.exports = dcartesianPower;
